#!/usr/bin/env node
// Assembles src/utils/patchNotesData.ts from the fragment files in
// src/patchNotes/entries/. Runs automatically via npm lifecycle hooks
// (postinstall, pretest, prestart/preandroid/preios) so the generated file
// is never committed and never conflicts between branches.
const fs = require('fs');
const path = require('path');

const entriesDir = path.join(__dirname, '..', 'src', 'patchNotes', 'entries');
const outFile = path.join(__dirname, '..', 'src', 'utils', 'patchNotesData.ts');

const files = fs.readdirSync(entriesDir).filter(f => f.endsWith('.json'));

const entries = files.map(file => {
  const data = JSON.parse(fs.readFileSync(path.join(entriesDir, file), 'utf8'));
  if (!data.message || !data.date) {
    throw new Error(`Patch note fragment ${file} must have "message" and "date"`);
  }
  return { message: data.message, date: data.date, file };
});

entries.sort((a, b) => {
  if (a.date !== b.date) return a.date < b.date ? 1 : -1;
  return a.file < b.file ? 1 : -1;
});

const body = entries
  .map(e => `  { message: ${JSON.stringify(e.message)}, date: ${JSON.stringify(e.date)} },`)
  .join('\n');

const output = `// AUTO-GENERATED by scripts/build-patch-notes.js — do not edit by hand.
// To add a patch note, create a new fragment in src/patchNotes/entries/
// instead; this file is regenerated automatically and is gitignored.
import type { PatchNote } from './patchNotes';

export const patchNotes: PatchNote[] = [
${body}
];
`;

fs.writeFileSync(outFile, output);
console.log(`build-patch-notes: wrote ${entries.length} entries to ${path.relative(process.cwd(), outFile)}`);
